    <div class=\"step-8-num\">03</div>\r\n          <div class=\"step-8-title\">Sourcing Network</div>\r\n          <div class=\"step-8-desc\">Connect with verified factories and suppliers upon request.</div>\r\n        </div>\r\n\r\n        <!-- Step 04 -->\r\n        <div class=\"step-8-item\">\r\n          <div class=\"step-8-num\">04</div>\r\n          <div class=\"step-8-title\">Production Monitoring</div>\r\n          <div class=\"step-8-desc\">Track production milestones aligned with client delivery schedules.</div>\r\n        </div>\r\n\r\n        <!-- Step 05 -->\r\n        <div class=\"step-8-item\">\r\n          <div class=\"step-8-num\">05</div>\r\n          <div class=\"step-8-title\">Quality Control</div>\r\n          <div class=\"step-8-desc\">On-site quality inspection before packaging and factory dispatch.</div>\r\n        </div>\r\n\r\n        <!-- Step 06 -->\r\n        <div class=\"step-8-item\">\r\n          <div class=\"step-8-num\">06</div>\r\n          <div class=\"step-8-title\">Documentation &amp; Clearance</div>\r\n          <div class=\"step-8-desc\">Prepare complete dossiers and handle customs export-import procedures.</div>\r\n        </div>\r\n\r\n        <!-- Step 07 -->\r\n        <div class=\"step-8-item\">\r\n          <div class=\"step-8-num\">07</div>\r\n          <div class=\"step-8-title\">Global Transportation</div>\r\n          <div class=\"step-8-desc\">Execute multi-modal transit via agreed air, ocean, or overland routes.</div>\r\n        </div>\r\n\r\n        <!-- Step 08 -->\r\n        <div class=\"step-8-item\">\r\n          <div class=\"step-8-num\">08</div>\r\n          <div class=\"step-8-title\">Completion &amp; Handover</div>\r\n          <div class=\"step-8-desc\">Finalize delivery and hand over all commercial &amp; customs documentation.</div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- 6. FREIGHT RATE TRANSPARENCY -->\r\n  <section class=\"route-rate-section\">\r\n    <div class=