peeGo Logistics)\r\n     Supports two variants: \'band\' (full-width 2-column) and \'sidebar\' (1-column card)\r\n     ========================================================================== -->\r\n\r\n<!-- TEMPLATE: VARIANT \"band\" (Dải ngang Full-width 2 cột nền Navy) -->\r\n<template id=\"tmpl-cta-band\">\r\n  <section class=\"cta-form-band-section\" id=\"contact-form\">\r\n    <div class=\"container cta-form-band-grid\">\r\n      <!-- Heading & hotline (trái) -->\r\n      <div class=\"cta-band-copy\">\r\n        <span class=\"section-tag\">{{TAG}}</span>\r\n        <h2 class=\"section-title section-title-white\">\r\n          {{HEADING}}\r\n        </h2>\r\n        <p class=\"cta-band-desc\">\r\n          {{SUBTEXT}}\r\n        </p>\r\n        <a href=\"tel:+84906828898\" class=\"cta-hotline-link\">\r\n          {{PHONE}}\r\n        </a>\r\n      </div>\r\n\r\n      <!-- Form trắng (phải) -->\r\n      <div class=\"cta-band-form\">\r\n        <div class=\"consult-card-white\">\r\n          <form class=\"consult-form\" onsubmit=\"handleConsultSubmit(event)\">\r\n            <div class=\"form-row-2col\">\r\n              <div class=\"form-group\">\r\n                <label class=\"form-label\" for=\"band_fullName\">{{LABEL_NAME}}</label>\r\n                <input type=\"text\" id=\"band_fullName\" class=\"form-control\" placeholder=\"{{PLACEHOLDER_NAME}}\" required>\r\n              </div>\r\n              <div class=\"form-group\">\r\n                <label class=\"form-label\" for=\"band_email\">{{LABEL_EMAIL}}</label>\r\n                <input type=\"email\" id=\"band_email\" class=\"form-control\" placeholder=\"{{PLACEHOLDER_EMAIL}}\" required>\r\n              </div>\r\n            </div>\r\n            <div class=\"form-group\">\r\n              <label class=\"form-label\" for=\"band_phone\">{{LABEL_PHONE}}</label>\r\n              <input type=\"tel\" id=\"band_phone\" class=\"form-control\" placeholder=\"{{PLACEHOLDER_PHONE}}\" required>\r\n            </div>\r\n            <div class=\"form-group\">\r\n              <label class=\"form-label\" for=\"band_message\">{{LABEL_MESSAGE}}</label>\r\n              <textarea id=\"band_message\" class=\"form-control\" placeholder=\"{{PLACEHOLDER_MESSAGE}}\"></textarea>\r\n            </div>\r\n            <button type=\"submit\" class=\"btn-orange btn-submit\">\r\n              {{BTN_SUBMIT}}\r\n            </button>\r\n            <p class=\"form-security-note\">\r\n              {{SECURITY_NOTE}}\r\n            </p>\r\n          </form>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n</template>\r\n\r\n<!-- TEMPLATE: VARIANT \"sidebar\" (Card hẹp 1 cột xếp chồng dọc nền Navy) -->\r\n<template id=\"tmpl-cta-sidebar\">\r\n  <div class=\"consult-card-sidebar\" id=\"contact-form\">\r\n    <span class=\"section-tag\">{{TAG}}</span>\r\n    <h3 class=\"sidebar-title\">{{HEADING}}</h3>\r\n    <p class=\"sidebar-desc\">{{SUBTEXT}}</p>\r\n    <div>\r\n      <a href=\"tel:+84906828898\" class=\"sidebar-hotline\">{{PHONE}}</a>\r\n    </div>\r\n\r\n    <form class=\"consult-form\" onsubmit=\"handleConsultSubmit(event)\">\r\n      <div class=\"form-group\">\r\n        <label class=\"form-label\" for=\"sidebar_fullName\">{{LABEL_NAME}}</label>\r\n        <input type=\"text\" id=\"sidebar_fullName\" class=\"form-control\" placeholder=\"{{PLACEHOLDER_NAME}}\" required>\r\n      </div>\r\n      <div class=\"form-group\">\r\n        <label class=\"form-label\" for=\"sidebar_email\">{{LABEL_EMAIL}}</label>\r\n        <input type=\"email\" id=\"sidebar_email\" class=\"form-control\" placeholder=\"{{PLACEHOLDER_EMAIL}}\" required>\r\n      </div>\r\n      <div class=\"form-group\">\r\n        <label class=\"form-label\" for=\"sidebar_phone\">{{LABEL_PHONE}}</label>\r\n        <input type=\"tel\" id=\"sidebar_phone\" class=\"form-control\" placeholder=\"{{PLACEHOLDER_PHONE}}\" required>\r\n      </div>\r\n      <div class=\"form-group\">\r\n        <label class=\"form-label\" for=\"sidebar_message\">{{LABEL_MESSAGE}}</label>\r\n        <textarea id=\"sidebar_message\" class=\"form-control\" placeholder=\"{{PLACEHOLDER_MESSAGE}}\"></textarea>\r\n      </div>\r\n      <button type=\"submit\" class=\"btn-orange btn-submit\">\r\n        {{BTN_SUBMIT}}\r\n      </button>\r\n      <p class=\"form-security-note\">\r\n        {{SECURITY_NOTE}}\r\n      </p>\r\n    </form>\r\n  </div>\r\n</template>\r\n','[Dùng chung] SpeeGo — Form đăng ký tư vấn &amp; Báo giá (Tiếng Việt)','','inherit','closed','closed','','117-revision-v1','','','2026-09-26 14:21:01','2026-09-26 14:21:01','',117,'http://localhost/wordpress_demo/?p=307',0,'revision','',0),(308,0,'2026-09-26 14:21:01','2026-09-26 14:21:01','<!-- =================================================================\r\n     HEADER & MULTI-LANGUAGE NAVIGATION (Exact Design Spec from Web Tổng)\r\n     ================================================================= -->\r\n<header id=\"masthead\" class=\"site-header speego-site-header\" role=\"banner\">\r\n  <!-- ================================================================\r\n     Top Bar: Hotline & Email\r\n     ================================================================ -->\r\n<div class=\"speego-header-topbar\">\r\n  <div class=\"speego-header-topbar-inner\">\r\n\r\n    <div\r\n      class=\"speego-header-contact\"\r\n      aria-label=\"SpeeGo contact details\"\r\n    >\r\n\r\n      <!-- Phone -->\r\n      <details class=\"speego-header-contact-popover\">\r\n        <summary\r\n          class=\"speego-header-contact-item\"\r\n          aria-label=\"Xem số điện thoại SpeeGo\"\r\n        >\r\n          <svg\r\n            class=\"speego-header-contact-icon speego-header-contact-icon-white\"\r\n            viewBox=\"0 0 24 24\"\r\n            fill=\"none\"\r\n            stroke=\"#FFFFFF\"\r\n            stroke-width=\"1.5\"\r\n            stroke-linecap=\"round\"\r\n            stroke-linejoin=\"round\"\r\n            aria-hidden=\"true\"\r\n